const result = $input.first().json;
const totalRows = Number(result.total_rows);
const missingNames = Number(result.missing_names);
const missingEmails = Number(result.missing_emails);
const missingEvents = Number(result.missing_events);
const missingTicketTypes = Number(result.missing_ticket_types);
const missingRegistrationDates = Number(result.missing_registration_dates);
const duplicateRegistrationCodes = Number(result.duplicate_registration_codes);

const issues = [];
if (totalRows === 0) issues.push('No event registrations were found.');
if (missingNames > 0) issues.push(`${missingNames} record(s) have a missing name.`);
if (missingEmails > 0) issues.push(`${missingEmails} record(s) have a missing email.`);
if (missingEvents > 0) issues.push(`${missingEvents} record(s) have a missing event name.`);
if (missingTicketTypes > 0) issues.push(`${missingTicketTypes} record(s) have a missing ticket type.`);
if (missingRegistrationDates > 0) issues.push(`${missingRegistrationDates} record(s) have a missing registration date.`);
if (duplicateRegistrationCodes > 0) issues.push(`${duplicateRegistrationCodes} duplicate registration code(s) found.`);

return [{
  json: {
    status: issues.length ? 'FAIL' : 'PASS',
    checked_at: new Date().toISOString(),
    total_rows: totalRows,
    missing_names: missingNames,
    missing_emails: missingEmails,
    missing_events: missingEvents,
    missing_ticket_types: missingTicketTypes,
    missing_registration_dates: missingRegistrationDates,
    duplicate_registration_codes: duplicateRegistrationCodes,
    message: issues.length ? `Data quality alert: ${issues.join(' ')}` : `Data quality check passed: ${totalRows} registrations checked.`
  }
}];
